import { v7 as uuidv7 } from "uuid";

/**
 * Generates an app-side, time-ordered UUIDv7 identifier.
 *
 * IDs are generated by the application (never by the database) so that
 * time-ordered, non-null workspace identifiers are available before insert.
 */
export function createId(): string {
  return uuidv7();
}
